import { WzPropertyType } from "../WzPropertyType.js";
import { WzExtended } from "../WzExtended.js";
import { WzIntProperty } from "./WzIntProperty.js";
/**
 * @public
 */
export class WzVectorProperty extends WzExtended {
    constructor(name = '', x, y) {
        super();
        this.name = '';
        this.parent = null;
        this.x = null;
        this.y = null;
        this.name = name;
        if (x != null)
            this.x = new WzIntProperty('', x);
        if (y != null)
            this.y = new WzIntProperty('', y);
    }
    get propertyType() {
        return WzPropertyType.Vector;
    }
    dispose() {
        if (this._disposed)
            return;
        if (this.x != null) {
            this.x.dispose();
            this.x = null;
        }
        if (this.y != null) {
            this.y.dispose();
            this.y = null;
        }
        this._disposed = true;
    }
    get wzValue() {
        return {
            x: this.x != null ? this.x.value : 0,
            y: this.y != null ? this.y.value : 0
        };
    }
    setValue(value) {
        if (this.x != null)
            this.x.setValue(value.x);
        if (this.y != null)
            this.y.setValue(value.y);
    }
    toString() {
        if (this.x != null && this.y != null) {
            return 'X: ' + this.x.value.toString() + ', Y: ' + this.y.value.toString();
        }
        return '';
    }
}
